'use client'

/**
 * BookingsHeatmap
 *
 * Renders a 7×N grid (days × hours) of booking frequency.
 * Default: hours 10–22 (13 cells). Fully keyboard-navigable + ARIA labelled.
 *
 * Color ramp (brand-locked):
 *   zero  → Stone 6% tint   (grid always visible, never invisible)
 *   low   → Onyx ramp       (intensity * 80%)
 *   peak  → Rust 80% tint   (hottest single cell)
 */

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const

export interface BookingsHeatmapProps {
  /** 7×N grid — rows are days (Sun=0…Sat=6), cols are hours. */
  data: number[][]
  /** First hour to display (inclusive). Default 10. */
  hourStart?: number
  /** Last hour to display (inclusive). Default 22. */
  hourEnd?: number
}

function cellBackground(value: number, max: number): string {
  if (value === 0 || max === 0) {
    // Stone floor — grid is always visible
    return 'color-mix(in oklch, var(--color-stone) 6%, transparent)'
  }
  const intensity = value / max
  if (intensity >= 1) {
    // Single hottest cell → Rust accent
    return 'color-mix(in oklch, var(--color-rust) 80%, transparent)'
  }
  // Onyx ramp 12%–76% (reserve 80% for rust peak)
  const pct = Math.round(12 + intensity * 64)
  return `color-mix(in oklch, var(--color-onyx) ${pct}%, transparent)`
}

export function BookingsHeatmap({
  data,
  hourStart = 10,
  hourEnd = 22,
}: BookingsHeatmapProps) {
  // Slice each row to the business-hour window
  const sliced = data.map((row) => row.slice(hourStart, hourEnd + 1))
  const hours = Array.from({ length: hourEnd - hourStart + 1 }, (_, i) => hourStart + i)
  const max = Math.max(...sliced.flat(), 1)

  // Hour labels every 2h within the window
  function hourLabel(h: number): string {
    return (h - hourStart) % 2 === 0 ? `${h}` : ''
  }

  return (
    <div className="overflow-x-auto">
      <div
        role="grid"
        aria-label="Booking frequency heatmap — business hours 10:00 to 22:00"
        className="inline-flex flex-col gap-1 min-w-max"
      >
        {/* Hour header row */}
        <div className="flex gap-1 pl-8" role="row" aria-hidden="true">
          {hours.map((h) => (
            <div
              key={h}
              role="columnheader"
              aria-label={`${h}:00`}
              className="w-4 text-center text-[9px] text-muted-foreground leading-none select-none"
            >
              {hourLabel(h)}
            </div>
          ))}
        </div>

        {/* Day rows */}
        {sliced.map((row, dayIndex) => {
          const dayLabel = DAYS[dayIndex] ?? `Day ${dayIndex}`
          return (
            <div key={dayIndex} role="row" className="flex items-center gap-1">
              {/* Day label */}
              <span
                role="rowheader"
                className="w-7 text-right text-[10px] text-muted-foreground shrink-0 select-none"
              >
                {dayLabel}
              </span>

              {/* Hour cells */}
              {row.map((val, colIndex) => {
                const hour = hourStart + colIndex
                const timeLabel = `${hour}:00`
                const bookingWord = val === 1 ? 'booking' : 'bookings'
                const ariaLabel = `${dayLabel} ${timeLabel} — ${val} ${bookingWord}`

                return (
                  <div
                    key={colIndex}
                    role="gridcell"
                    tabIndex={0}
                    aria-label={ariaLabel}
                    title={ariaLabel}
                    className="h-4 w-4 rounded-sm outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-rust)] focus-visible:ring-offset-1 cursor-default"
                    style={{ backgroundColor: cellBackground(val, max) }}
                  />
                )
              })}
            </div>
          )
        })}
      </div>

      <p className="mt-3 text-xs text-muted-foreground">
        Lighter = fewer bookings. Darker = more. Peak hour shown in rust.
      </p>
    </div>
  )
}

'use client'

/**
 * StatusBreakdownBar
 *
 * Stacked horizontal bar showing all booking statuses summing to total.
 * Brand color map:
 *   success     → Onyx fill  (completed)
 *   neutral     → Stone fill (pending, confirmed, in_progress, rescheduled)
 *   destructive → Rust fill  (no_show, cancelled)
 */

export interface StatusSegment {
  key: string
  label: string
  count: number
  tone: 'success' | 'neutral' | 'destructive'
}

export interface StatusBreakdownBarProps {
  statuses: StatusSegment[]
  total: number
}

const TONE_FILL: Record<StatusSegment['tone'], string> = {
  success: 'var(--color-onyx)',
  neutral: 'var(--color-stone)',
  destructive: 'var(--color-rust)',
}

const TONE_DOT_CLASS: Record<StatusSegment['tone'], string> = {
  success: 'bg-[var(--color-onyx)]',
  neutral: 'bg-[var(--color-stone)]',
  destructive: 'bg-[var(--color-rust)]',
}

export function StatusBreakdownBar({ statuses, total }: StatusBreakdownBarProps) {
  if (total === 0) {
    return (
      <p className="text-xs text-muted-foreground italic">No bookings in this period.</p>
    )
  }

  // Build aria label summarising all segments
  const segmentSummary = statuses
    .filter((s) => s.count > 0)
    .map((s) => `${s.count} ${s.label.toLowerCase()}`)
    .join(', ')
  const ariaLabel = `Booking status breakdown: ${segmentSummary}, ${total} total`

  return (
    <div className="space-y-3">
      {/* Stacked bar */}
      <div
        role="img"
        aria-label={ariaLabel}
        className="flex h-8 w-full overflow-hidden rounded-full"
      >
        {statuses
          .filter((s) => s.count > 0)
          .map((s, i, arr) => {
            const widthPct = (s.count / total) * 100
            const isFirst = i === 0
            const isLast = i === arr.length - 1
            return (
              <div
                key={s.key}
                title={`${s.label}: ${s.count} (${Math.round(widthPct)}%)`}
                className="h-full transition-all"
                style={{
                  width: `${widthPct}%`,
                  backgroundColor: TONE_FILL[s.tone],
                  borderRadius: isFirst && isLast
                    ? '9999px'
                    : isFirst
                    ? '9999px 0 0 9999px'
                    : isLast
                    ? '0 9999px 9999px 0'
                    : '0',
                }}
              />
            )
          })}
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-x-4 gap-y-2">
        {statuses.map((s) => {
          const pct = total > 0 ? Math.round((s.count / total) * 100) : 0
          return (
            <div key={s.key} className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <span
                className={`inline-block h-2.5 w-2.5 shrink-0 rounded-full ${TONE_DOT_CLASS[s.tone]}`}
                aria-hidden="true"
              />
              <span className="font-medium text-foreground">{s.label}</span>
              <span className="tabular-nums">{s.count}</span>
              <span className="tabular-nums opacity-60">({pct}%)</span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

