import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange, rangeDays, pickGroupBy } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
  group_by: z.enum(['day', 'week', 'month']).optional(),
})

/** Business-hour window trimmed server-side to reduce payload. */
const HEATMAP_HOUR_START = 10
const HEATMAP_HOUR_END = 22 // inclusive → 13 cells

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

/** Per-status breakdown — every booking lands in exactly one bucket. Sum == kpis.total. */
interface StatusBreakdown {
  completed: number
  no_show: number
  cancelled: number
  pending: number
  confirmed: number
  in_progress: number
  rescheduled: number
  other: number
}

interface TimelineItem {
  period: string
  count: number
}

interface ServiceRankItem {
  name: string
  count: number
}

interface BookingsBlock {
  kpis: BookingKpis
  /** Status breakdown — all counts sum to kpis.total. */
  statusBreakdown: StatusBreakdown
  /** Heatmap trimmed to business hours 10–22 (13 cols × 7 rows). */
  timeline: TimelineItem[]
  heatmap: number[][]
  serviceRanking: ServiceRankItem[]
}

async function fetchBookings(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string,
  to: string,
  groupBy: 'day' | 'week' | 'month',
): Promise<BookingsBlock> {
  const { data: bookings, error } = await supabase
    .from('bookings')
    .select('id, status, scheduled_at, service_id, source, services(name)')
    .eq('studio_id', studioId)
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)
    .order('scheduled_at', { ascending: true })

  if (error) throw error

  const all = bookings ?? []
  const total = all.length

  // Status breakdown — every booking classified into exactly one bucket
  const statusBreakdown: StatusBreakdown = {
    completed: 0,
    no_show: 0,
    cancelled: 0,
    pending: 0,
    confirmed: 0,
    in_progress: 0,
    rescheduled: 0,
    other: 0,
  }
  for (const b of all) {
    const s = b.status as string
    switch (s) {
      case 'completed':
        statusBreakdown.completed++
        break
      case 'no_show':
        statusBreakdown.no_show++
        break
      case 'cancelled':
        statusBreakdown.cancelled++
        break
      case 'pending':
        statusBreakdown.pending++
        break
      case 'confirmed':
        statusBreakdown.confirmed++
        break
      case 'in_progress':
        statusBreakdown.in_progress++
        break
      case 'rescheduled':
        statusBreakdown.rescheduled++
        break
      default:
        logger.warn({ studioId, status: s }, 'bookings report: unknown status encountered')
        statusBreakdown.other++
    }
  }

  const completed = statusBreakdown.completed
  const noShows = statusBreakdown.no_show
  const cancelled = statusBreakdown.cancelled

  // Timeline grouped by period
  const grouped = all.reduce<Record<string, number>>((acc, b) => {
    const d = new Date(b.scheduled_at)
    let key: string
    if (groupBy === 'month') {
      key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    } else if (groupBy === 'week') {
      const dow = d.getDay()
      const startOfWeek = new Date(d)
      startOfWeek.setDate(d.getDate() - dow)
      key = startOfWeek.toISOString().slice(0, 10)
    } else {
      key = d.toISOString().slice(0, 10)
    }
    acc[key] = (acc[key] ?? 0) + 1
    return acc
  }, {})

  const timeline = Object.entries(grouped)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([period, count]) => ({ period, count }))

  // Day × hour heatmap — trimmed server-side to business hours 10–22 (13 cols)
  const heatmapCols = HEATMAP_HOUR_END - HEATMAP_HOUR_START + 1 // 13
  const heatmap: number[][] = Array.from({ length: 7 }, () =>
    Array.from<number>({ length: heatmapCols }).fill(0),
  )
  for (const b of all) {
    const d = new Date(b.scheduled_at)
    const h = d.getHours()
    if (h < HEATMAP_HOUR_START || h > HEATMAP_HOUR_END) continue
    const row = heatmap[d.getDay()]
    const col = h - HEATMAP_HOUR_START
    if (row) row[col] = (row[col] ?? 0) + 1
  }

  // Service popularity — null service_id grouped as "Walk-in / Unscheduled"
  const serviceCounts = all.reduce<Record<string, { name: string; count: number }>>((acc, b) => {
    const key = b.service_id ?? '__walkin__'
    const svc = b.services
    const name = b.service_id
      ? (Array.isArray(svc)
          ? (svc[0]?.name ?? b.service_id)
          : ((svc as { name?: string } | null)?.name ?? b.service_id))
      : 'Walk-in / Unscheduled'
    if (!acc[key]) acc[key] = { name, count: 0 }
    acc[key]!.count++
    return acc
  }, {})

  const serviceRanking = Object.values(serviceCounts).sort((a, b) => b.count - a.count)

  return {
    kpis: {
      total,
      completed,
      noShows,
      cancelled,
      noShowRate: total > 0 ? Math.round((noShows / total) * 100) : 0,
      cancellationRate: total > 0 ? Math.round((cancelled / total) * 100) : 0,
    },
    statusBreakdown,
    timeline,
    heatmap,
    serviceRanking,
  }
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { compare, group_by } = parsed.data
  const supabase = await createClient()
  const { current } = parseRange(req.nextUrl.searchParams)

  const days = rangeDays(current)
  const resolvedGroupBy = group_by ?? pickGroupBy(days)

  try {
    if (compare === '1') {
      const prior = priorRange(current)
      const [currentBlock, priorBlock] = await Promise.all([
        fetchBookings(supabase, auth.studioId, current.from, current.to, resolvedGroupBy),
        fetchBookings(supabase, auth.studioId, prior.from, prior.to, resolvedGroupBy),
      ])
      return Response.json({ current: currentBlock, prior: priorBlock })
    }

    const currentBlock = await fetchBookings(
      supabase,
      auth.studioId,
      current.from,
      current.to,
      resolvedGroupBy,
    )
    return Response.json({ current: currentBlock })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'bookings report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

