interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface StatusBreakdown {
  completed: number
  no_show: number
  cancelled: number
  pending: number
  confirmed: number
  in_progress: number
  rescheduled: number
  other: number
}

interface BookingsBlock {
  kpis: BookingKpis
  statusBreakdown: StatusBreakdown
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][]
  serviceRanking: Array<{ name: string; count: number }>
}

interface BookingsResponse {
  current: BookingsBlock
  prior?: BookingsBlock
}

