/**
 * Bookings report aggregation unit tests (Vitest)
 *
 * Covers:
 * - serviceCounts reducer with mixed / null / duplicate service_ids
 * - Status breakdown sums to total
 * - Heatmap dimensions after business-hour trim (7×13 for hours 10-22)
 * - pickGroupBy thresholds from lib/analytics/range
 */

import { describe, it, expect } from 'vitest'
import { pickGroupBy } from '@/lib/analytics/range'

// ─────────────────────────────────────────────────────────────────────────────
// Helpers — pure functions extracted from the route logic for testability
// ─────────────────────────────────────────────────────────────────────────────

type RawBooking = {
  service_id: string | null
  services: { name: string } | null
  status: string
  scheduled_at: string
}

type ServiceCount = { name: string; count: number }

function buildServiceCounts(bookings: RawBooking[]): Record<string, ServiceCount> {
  return bookings.reduce<Record<string, ServiceCount>>((acc, b) => {
    const key = b.service_id ?? '__walkin__'
    const name = b.service_id
      ? (b.services?.name ?? b.service_id)
      : 'Walk-in / Unscheduled'
    if (!acc[key]) acc[key] = { name, count: 0 }
    acc[key]!.count++
    return acc
  }, {})
}

type StatusBreakdown = {
  completed: number
  no_show: number
  cancelled: number
  pending: number
  confirmed: number
  in_progress: number
  rescheduled: number
  other: number
}

function buildStatusBreakdown(bookings: RawBooking[]): StatusBreakdown {
  const bd: StatusBreakdown = {
    completed: 0,
    no_show: 0,
    cancelled: 0,
    pending: 0,
    confirmed: 0,
    in_progress: 0,
    rescheduled: 0,
    other: 0,
  }
  for (const b of bookings) {
    switch (b.status) {
      case 'completed':   bd.completed++;   break
      case 'no_show':     bd.no_show++;     break
      case 'cancelled':   bd.cancelled++;   break
      case 'pending':     bd.pending++;     break
      case 'confirmed':   bd.confirmed++;   break
      case 'in_progress': bd.in_progress++; break
      case 'rescheduled': bd.rescheduled++; break
      default:            bd.other++
    }
  }
  return bd
}

const HEATMAP_HOUR_START = 10
const HEATMAP_HOUR_END = 22 // inclusive

function buildHeatmap(bookings: RawBooking[]): number[][] {
  const cols = HEATMAP_HOUR_END - HEATMAP_HOUR_START + 1 // 13
  const heatmap: number[][] = Array.from({ length: 7 }, () =>
    Array.from<number>({ length: cols }).fill(0),
  )
  for (const b of bookings) {
    const d = new Date(b.scheduled_at)
    const h = d.getHours()
    if (h < HEATMAP_HOUR_START || h > HEATMAP_HOUR_END) continue
    const row = heatmap[d.getDay()]
    const col = h - HEATMAP_HOUR_START
    if (row) row[col] = (row[col] ?? 0) + 1
  }
  return heatmap
}

// ─────────────────────────────────────────────────────────────────────────────
// Fixtures
// ─────────────────────────────────────────────────────────────────────────────

const fixedDay = (hour: number) => `2026-04-07T${String(hour).padStart(2, '0')}:00:00.000Z` // Tuesday

const MIXED_BOOKINGS: RawBooking[] = [
  // service A × 3
  { service_id: 'svc-a', services: { name: 'Small Tattoo' }, status: 'completed', scheduled_at: fixedDay(11) },
  { service_id: 'svc-a', services: { name: 'Small Tattoo' }, status: 'completed', scheduled_at: fixedDay(14) },
  { service_id: 'svc-a', services: { name: 'Small Tattoo' }, status: 'no_show',   scheduled_at: fixedDay(16) },
  // service B × 1
  { service_id: 'svc-b', services: { name: 'Half Sleeve' }, status: 'confirmed',  scheduled_at: fixedDay(10) },
  // walk-in (null service) × 2
  { service_id: null, services: null, status: 'pending',   scheduled_at: fixedDay(13) },
  { service_id: null, services: null, status: 'cancelled', scheduled_at: fixedDay(20) },
]

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

describe('serviceCounts reducer', () => {
  it('counts distinct service_ids correctly', () => {
    const counts = buildServiceCounts(MIXED_BOOKINGS)
    expect(counts['svc-a']?.count).toBe(3)
    expect(counts['svc-b']?.count).toBe(1)
    expect(counts['__walkin__']?.count).toBe(2)
  })

  it('labels null service_id as Walk-in / Unscheduled', () => {
    const counts = buildServiceCounts(MIXED_BOOKINGS)
    expect(counts['__walkin__']?.name).toBe('Walk-in / Unscheduled')
  })

  it('uses service name from joined services row', () => {
    const counts = buildServiceCounts(MIXED_BOOKINGS)
    expect(counts['svc-a']?.name).toBe('Small Tattoo')
    expect(counts['svc-b']?.name).toBe('Half Sleeve')
  })

  it('falls back to service_id when services row is null', () => {
    const bookings: RawBooking[] = [
      { service_id: 'svc-orphan', services: null, status: 'completed', scheduled_at: fixedDay(11) },
    ]
    const counts = buildServiceCounts(bookings)
    expect(counts['svc-orphan']?.name).toBe('svc-orphan')
  })

  it('handles empty bookings array', () => {
    const counts = buildServiceCounts([])
    expect(Object.keys(counts)).toHaveLength(0)
  })

  it('handles all-null service_ids', () => {
    const bookings: RawBooking[] = [
      { service_id: null, services: null, status: 'completed', scheduled_at: fixedDay(11) },
      { service_id: null, services: null, status: 'pending',   scheduled_at: fixedDay(12) },
    ]
    const counts = buildServiceCounts(bookings)
    expect(Object.keys(counts)).toHaveLength(1)
    expect(counts['__walkin__']?.count).toBe(2)
  })
})

describe('status breakdown', () => {
  it('all counts sum to total bookings', () => {
    const bd = buildStatusBreakdown(MIXED_BOOKINGS)
    const sum =
      bd.completed + bd.no_show + bd.cancelled + bd.pending +
      bd.confirmed + bd.in_progress + bd.rescheduled + bd.other
    expect(sum).toBe(MIXED_BOOKINGS.length)
  })

  it('classifies each status correctly', () => {
    const bd = buildStatusBreakdown(MIXED_BOOKINGS)
    expect(bd.completed).toBe(2)
    expect(bd.no_show).toBe(1)
    expect(bd.confirmed).toBe(1)
    expect(bd.pending).toBe(1)
    expect(bd.cancelled).toBe(1)
    expect(bd.in_progress).toBe(0)
    expect(bd.rescheduled).toBe(0)
    expect(bd.other).toBe(0)
  })

  it('routes unknown status to other bucket', () => {
    const bookings: RawBooking[] = [
      { service_id: null, services: null, status: 'ghost_status', scheduled_at: fixedDay(11) },
      { service_id: null, services: null, status: 'completed',    scheduled_at: fixedDay(12) },
    ]
    const bd = buildStatusBreakdown(bookings)
    expect(bd.other).toBe(1)
    expect(bd.completed).toBe(1)
    const total = Object.values(bd).reduce((a, b) => a + b, 0)
    expect(total).toBe(bookings.length)
  })

  it('returns all zeros for empty bookings', () => {
    const bd = buildStatusBreakdown([])
    const sum = Object.values(bd).reduce((a, b) => a + b, 0)
    expect(sum).toBe(0)
  })
})

describe('heatmap dimensions', () => {
  it('produces 7 rows (one per day)', () => {
    const heatmap = buildHeatmap(MIXED_BOOKINGS)
    expect(heatmap).toHaveLength(7)
  })

  it('produces 13 columns (hours 10-22 inclusive)', () => {
    const heatmap = buildHeatmap(MIXED_BOOKINGS)
    for (const row of heatmap) {
      expect(row).toHaveLength(13)
    }
  })

  it('correctly slots bookings into hour columns', () => {
    // fixedDay(11) = 11:00 UTC → col 1 (11-10=1)
    // fixedDay(14) = 14:00 UTC → col 4
    // fixedDay(16) = 16:00 UTC → col 6
    const heatmap = buildHeatmap(MIXED_BOOKINGS)
    const tuesdayRow = heatmap[2]! // 2026-04-07 is Tuesday (day index 2)
