/**
 * Build a local-time ISO string so d.getHours() / d.getDay() in the heatmap
 * function returns the intended values regardless of the test runner's TZ.
 * We use local midnight + offset to pin the exact local hour.
 */
function localIso(dayOffset: number, hour: number): string {
  const d = new Date()
  d.setHours(hour, 0, 0, 0)
  d.setDate(d.getDate() + dayOffset)
  return d.toISOString()
}

